"""Seal only the current public snapshot, without rewriting research reports."""
import gzip,hashlib,json
from pathlib import Path
b=Path(__file__).resolve().parents[1]/'breakthrough-assessment-20261020';latest=json.loads((b/'LATEST.json').read_bytes());p=b/latest['snapshot'];assert p.parent==b/'snapshots'and p.is_dir();assert not(p/'SNAPSHOT-MANIFEST.json').exists();sha=lambda b:hashlib.sha256(b).hexdigest();raw=(p/'public-submissions.json').read_bytes();json.loads(raw);(p/'public-submissions.json.gz').write_bytes(gzip.compress(raw,mtime=0));files=['leader-product.json','leader-qubits.json','leader-toffoli.json','PUBLIC-RECORDS.json','public-submissions.json.gz'];(p/'SNAPSHOT-MANIFEST.json').write_bytes((json.dumps({'raw_api_sha256':sha(raw),'files':{n:sha((p/n).read_bytes())for n in files},'scope':'Fresh immutable public snapshot. Prior snapshots remain historical evidence.'},indent=2)+'\n').encode());(p/'.gitattributes').write_bytes(b'* -text\n');print(latest['snapshot'],'sealed')
